function UserForm({lang,onSave}){const [f,setF]=useState({email:'',password:'',full_name:'',role:'teacher',teacher_code:'',home_centre_code:'PVT',region_no:1,professional_level:'',language_preference:'en'});return <form onSubmit={e=>{e.preventDefault();onSave({...f,region_no:Number(f.region_no)})}}><div className="form-grid two"><Field label={t(lang,'fullName')}><input required value={f.full_name} onChange={e=>setF({...f,full_name:e.target.value})}/></Field><Field label={t(lang,'email')}><input required type="email" value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></Field><Field label={t(lang,'temporaryPassword')}><input required type="password" minLength="8" value={f.password} onChange={e=>setF({...f,password:e.target.value})}/></Field><Field label={t(lang,'role')}><select value={f.role} onChange={e=>setF({...f,role:e.target.value})}>{Object.entries(ROLE_LABELS).map(([k,v])=><option key={k} value={k}>{v.en}</option>)}</select></Field><Field label={t(lang,'teacherCode')}><input value={f.teacher_code} onChange={e=>setF({...f,teacher_code:e.target.value})}/></Field><Field label={t(lang,'level')}><input value={f.professional_level} onChange={e=>setF({...f,professional_level:e.target.value})}/></Field><Field label={t(lang,'region')}><select value={f.region_no} onChange={e=>{const r=Number(e.target.value);setF({...f,region_no:r,home_centre_code:REGION_CENTRES[r][0]})}}>{[1,2,3].map(r=><option key={r} value={r}>Region {r}</option>)}</select></Field><Field label={t(lang,'centre')}><select value={f.home_centre_code} onChange={e=>setF({...f,home_centre_code:e.target.value})}>{REGION_CENTRES[f.region_no].map(c=><option key={c}>{c}</option>)}</select></Field></div><div className="insight" style={{margin:'13px 0 0'}}><b>Security</b><p>Account creation runs on the server with the Supabase service-role key. The key is never exposed to the browser.</p></div><FormActions lang={lang}/></form>}
function TouchpointForm({teachers,defaultTeacher,lang,onSave}){const [f,setF]=useState({teacher_id:defaultTeacher?.id||teachers[0]?.id||'',touch_date:nowDate(),touch_type:'Feedback / coaching',notes:''});return <form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="form-grid two"><Field label="Teacher"><select value={f.teacher_id} onChange={e=>setF({...f,teacher_id:e.target.value})}>{teachers.map(x=><option key={x.id} value={x.id}>{x.full_name}</option>)}</select></Field><Field label="Date"><input type="date" value={f.touch_date} onChange={e=>setF({...f,touch_date:e.target.value})}/></Field><Field label="Touch type"><select value={f.touch_type} onChange={e=>setF({...f,touch_type:e.target.value})}><option>Observation</option><option>Feedback / coaching</option><option>Catch-up meeting</option><option>Retraining follow-up</option><option>Performance conversation</option></select></Field></div><div style={{marginTop:12}}><Field label="Notes / evidence"><textarea value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></Field></div><FormActions lang={lang}/></form>}
function UpgradeForm({teacher,lang,onSave}){const [f,setF]=useState({teacher_id:teacher.id,current_level:teacher.professional_level||'',proposed_level:'',rationale:'',evidence_summary:''});return <form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="form-grid two"><Field label="Teacher"><input value={teacher.full_name} readOnly/></Field><Field label="Current level"><input value={f.current_level} readOnly/></Field><Field label="Proposed level"><input required value={f.proposed_level} onChange={e=>setF({...f,proposed_level:e.target.value})}/></Field></div><div className="form-grid two" style={{marginTop:12}}><Field label="Required rationale"><textarea required value={f.rationale} onChange={e=>setF({...f,rationale:e.target.value})}/></Field><Field label="Evidence summary"><textarea required value={f.evidence_summary} onChange={e=>setF({...f,evidence_summary:e.target.value})}/></Field></div><FormActions lang={lang}/></form>}
function DocumentForm({teachers,lang,onSave}){const [file,setFile]=useState(null);const [f,setF]=useState({teacher_id:teachers[0]?.id||'',degree_status:'Missing',tesol_status:'Missing',english_status:'Missing',native_proof_status:'N/A',promised_submission_date:'',completion_pct:0,document_type:'degree'});return <form onSubmit={e=>{e.preventDefault();onSave(f,file)}}><div className="form-grid two"><Field label="Teacher"><select value={f.teacher_id} onChange={e=>setF({...f,teacher_id:e.target.value})}>{teachers.map(x=><option key={x.id} value={x.id}>{x.full_name}</option>)}</select></Field><Field label={t(lang,'degree')}><StatusSelect value={f.degree_status} onChange={v=>setF({...f,degree_status:v})}/></Field><Field label={t(lang,'tesol')}><StatusSelect value={f.tesol_status} onChange={v=>setF({...f,tesol_status:v})}/></Field><Field label="English qualification"><StatusSelect value={f.english_status} onChange={v=>setF({...f,english_status:v})}/></Field><Field label="Native proof"><StatusSelect value={f.native_proof_status} onChange={v=>setF({...f,native_proof_status:v})} allowNA/></Field><Field label={t(lang,'promisedDate')}><input type="date" value={f.promised_submission_date} onChange={e=>setF({...f,promised_submission_date:e.target.value})}/></Field><Field label="Completion %"><input type="number" min="0" max="100" value={f.completion_pct} onChange={e=>setF({...f,completion_pct:e.target.value})}/></Field><Field label="Upload as"><select value={f.document_type} onChange={e=>setF({...f,document_type:e.target.value})}><option value="degree">Degree</option><option value="tesol">TESOL / pedagogy</option><option value="english">English qualification</option><option value="native-proof">Native proof</option><option value="other">Other</option></select></Field><Field label="Document file"><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)}/></Field></div><FormActions lang={lang}/></form>}

function SupportForm({teacher,lang,onSave}){const [f,setF]=useState({teacher_id:teacher?.id||'',category:'Academic / Methodology',subject:'',details:'',routed_to:'Academic Supervisor / R&D'});const route={ 'Academic / Methodology':'Academic Supervisor / R&D','Resource / Broken link':'R&D','Schedule / Centre coordination':'CMO / Centre Director','Learner / Service':'CSR','Documents / Certificates':'PTNS','Other':'R&D' };return <form onSubmit={e=>{e.preventDefault();onSave(f)}}><div className="form-grid two"><Field label="Teacher"><input value={teacher?.full_name||''} readOnly/></Field><Field label="Category"><select value={f.category} onChange={e=>{const category=e.target.value;setF({...f,category,routed_to:route[category]})}}>{Object.keys(route).map(x=><option key={x}>{x}</option>)}</select></Field><Field label="Subject"><input required value={f.subject} onChange={e=>setF({...f,subject:e.target.value})}/></Field><Field label="Route to"><input value={f.routed_to} readOnly/></Field></div><div style={{marginTop:12}}><Field label={lang==='vi'?'Chi tiết / ngữ cảnh':'Details / context'}><textarea required value={f.details} onChange={e=>setF({...f,details:e.target.value})}/></Field></div><FormActions lang={lang}/></form>}

function StatusSelect({value,onChange,allowNA}){return <select value={value} onChange={e=>onChange(e.target.value)}>{allowNA&&<option>N/A</option>}<option>Missing</option><option>Pending</option><option>Verified</option></select>}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>}
function FormActions({lang}){return <div style={{display:'flex',justifyContent:'flex-end',marginTop:17}}><button className="btn primary">{t(lang,'save')} →</button></div>}
